package dk.jamesbabz.madkursus.outbound.mealplan;
import java.util.*; import dk.jamesbabz.madkursus.outbound.mealplan.details.*; import dk.jamesbabz.madkursus.outbound.recipe.details.RecipeEntity; import dk.jamesbabz.madkursus.service.exceptions.ResourceNotFoundException; import dk.jamesbabz.madkursus.service.models.*; import dk.jamesbabz.madkursus.service.ports.*; import jakarta.persistence.EntityManager; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component @RequiredArgsConstructor public class MealPlanAdapterImpl implements MealPlanPort { private final MealPlanJpaRepository repository; private final EntityManager entityManager; private final RecipePort recipePort;
 @Transactional public MealPlan save(MealPlan model){boolean creating=model.id()==null;MealPlanEntity entity;if(creating){entity=new MealPlanEntity(null,model.userId(),model.name(),model.createdAt(),model.updatedAt());for(PlannedRecipe r:model.recipes())entity.addRecipe(new PlannedRecipeEntity(null,recipeRef(r),r.portions(),r.sortOrder(),r.status()));entity=repository.saveAndFlush(entity);}else{entity=repository.findByIdAndUserId(model.id(),model.userId()).orElseThrow(()->new ResourceNotFoundException("Meal plan",model.id()));entity.update(model.name(),model.updatedAt());Set<UUID>wanted=model.recipes().stream().map(PlannedRecipe::id).filter(Objects::nonNull).collect(java.util.stream.Collectors.toSet());entity.getRecipes().removeIf(existing->!wanted.contains(existing.getId()));Map<UUID,PlannedRecipeEntity> existing=new HashMap<>();int temporary=1_000_000;for(PlannedRecipeEntity child:entity.getRecipes()){existing.put(child.getId(),child);child.update(child.getRecipe(),child.getPortions(),temporary++,child.getStatus());}repository.flush();for(PlannedRecipe r:model.recipes()){PlannedRecipeEntity child=r.id()==null?null:existing.get(r.id());if(child==null)entity.addRecipe(new PlannedRecipeEntity(null,recipeRef(r),r.portions(),r.sortOrder(),r.status()));else child.update(recipeRef(r),r.portions(),r.sortOrder(),r.status());}repository.flush();}return map(entity);}
 @Transactional(readOnly=true) public Optional<MealPlan> findByIdAndUserId(UUID id,UUID userId){return repository.findByIdAndUserId(id,userId).map(this::map);} @Transactional(readOnly=true) public List<MealPlan> findAllByUserId(UUID userId){return repository.findAllByUserIdOrderByUpdatedAtDesc(userId).stream().map(this::map).toList();} @Transactional public void deleteByIdAndUserId(UUID id,UUID userId){repository.deleteByIdAndUserId(id,userId);}
 private MealPlan map(MealPlanEntity e){return new MealPlan(e.getId(),e.getUserId(),e.getName(),e.getCreatedAt(),e.getUpdatedAt(),e.getRecipes().stream().map(r->new PlannedRecipe(r.getId(),recipePort.findByIdAndUserId(r.getRecipe().getId(),e.getUserId()).orElseThrow(()->new ResourceNotFoundException("Recipe",r.getRecipe().getId())),r.getPortions(),r.getSortOrder(),r.getStatus())).toList());}
 private RecipeEntity recipeRef(PlannedRecipe r){return entityManager.getReference(RecipeEntity.class,r.recipe().id());}
}
